{"query": "WITH s AS (SELECT sample_unique_id, attribute_value ct FROM clinical_data_derived WHERE cancer_study_identifier='msk_impact_50k_2026' AND attribute_name='CANCER_TYPE_DETAILED'),
prof AS (SELECT sample_unique_id FROM mutation_panel_gene_coverage WHERE hugo_gene_symbol='BRIP1' AND cancer_study_identifier='msk_impact_50k_2026'),
alt AS (SELECT DISTINCT sample_unique_id, mutation_variant, mutation_type FROM genomic_event_derived WHERE cancer_study_identifier='msk_impact_50k_2026' AND hugo_gene_symbol='BRIP1' AND variant_type='mutation' AND mutation_status!='UNCALLED' AND off_panel=0)
SELECT s.ct, count(DISTINCT s.sample_unique_id) profiled, count(DISTINCT alt.sample_unique_id) altered FROM s JOIN prof USING sample_unique_id LEFT JOIN alt USING sample_unique_id WHERE s.ct IN ('Sarcomatoid Carcinoma of the Lung','Lung Adenocarcinoma','Lung Squamous Cell Carcinoma','Small Cell Lung Cancer') GROUP BY s.ct;
"}
